def compute_changes(old, new):
    """Return (added, modified, removed) name lists."""
    added = []
    modified = []
    removed = []
    for name in old:
        if name not in new:
            removed.append(name)
        elif old[name] != new[name]:
            modified.append(name)
    for name in new:
        if name not in old:
            added.append(name)
    return added, modified, removed
